def transform(grid):
    h, w = len(grid), len(grid[0])

    # The 3s form a full horizontal or vertical band; its width is the
    # motif's interior size.
    runs = []
    for r in range(h):
        if all(v == 3 for v in grid[r]):
            runs.append(("h", r))
    for c in range(w):
        if all(grid[r][c] == 3 for r in range(h)):
            runs.append(("v", c))

    if runs:
        orientation, _ = runs[0]
        indices = [i for i in range(h if orientation == "h" else w)
                   if (all(v == 3 for v in grid[i]) if orientation == "h"
                       else all(grid[r][i] == 3 for r in range(h)))]
        k = len(indices)
    else:
        k = 0

    if k == 0:
        return [row[:] for row in grid]

    pitch = k + 1
    patterns = {}
    for r0 in range(0, h, pitch):
        for c0 in range(0, w, pitch):
            if r0 + k > h or c0 + k > w:
                continue
            block = tuple(tuple(grid[r0 + a][c0 + b] for b in range(k))
                          for a in range(k))
            if any(v == 3 for row in block for v in row):
                continue
            if any(v == 2 for row in block for v in row):
                patterns[block] = patterns.get(block, 0) + 1

    if not patterns:
        return [[0 if v == 3 else v for v in row] for row in grid]

    template = max(patterns, key=patterns.get)
    out = [[0] * w for _ in range(h)]

    for i, r0 in enumerate(range(0, h, pitch)):
        for j, c0 in enumerate(range(0, w, pitch)):
            if i >= k or j >= k or template[i][j] != 2:
                continue
            for a in range(k):
                for b in range(k):
                    if r0 + a < h and c0 + b < w and template[a][b] == 2:
                        out[r0 + a][c0 + b] = 2
            out[r0 + i][c0 + j] = 8

    return out
